WORKSPACE_FILE_ROLES = ("law", "map", "record", "memory", "boundary")
# Optional, versioned Vivary metadata lives under [workspace.vivary]. Unchanged
# thin-v0.3 workspaces omit it and keep thin-context defaults. Files generated by
# the previous source wrote the same patterns/roles shape directly under
# [workspace]; recognized legacy assignments still describe roles, while
# unrelated or malformed workspace.patterns/workspace.roles values stay ignored.
WORKSPACE_VIVARY_METADATA_VERSION = 1


def resolve_workspace_roles(workspace, protected_paths):
    """Describe exact relative paths without discovering files or granting access.

    `protected_paths` are the validated private, runtime, and capability storage
    paths. The thin-context boundary describes them without widening privacy.
    The thin-context map is the existing context Routes section, not a generated
    inventory. STATE ownership remains in workspace.state, outside these roles.
    """
    metadata = workspace.get("vivary")
    if metadata is None:
        return _legacy_workspace_roles(workspace, protected_paths)
    if not isinstance(metadata, dict):
        raise ConfigError("workspace.vivary must be a table")
    version = metadata.get("version")
    if isinstance(version, bool) or version != WORKSPACE_VIVARY_METADATA_VERSION:
        raise ConfigError(
            f"workspace.vivary.version must be {WORKSPACE_VIVARY_METADATA_VERSION}"
        )
    patterns, overrides = _workspace_role_assignments(metadata, "workspace.vivary")
    return _describe_workspace_roles(patterns, overrides, protected_paths, "vivary.roles")


def _legacy_workspace_roles(workspace, protected_paths):
    """Read pre-[workspace.vivary] assignments without rewriting the file.

    Only a file that carries both legacy keys is a candidate. Its values are
    checked with the same shape rules as the explicit table; anything the
    supported shape does not recognize keeps the thin-context defaults it
    always had. Legacy reads describe roles only and never widen privacy.
    """
    if "patterns" not in workspace or "roles" not in workspace:
        return _describe_workspace_roles(["thin-context"], {}, protected_paths)
    try:
        patterns, overrides = _workspace_role_assignments(workspace, "workspace")
        return _describe_workspace_roles(patterns, overrides, protected_paths, "roles")
    except ConfigError:
        return _describe_workspace_roles(["thin-context"], {}, protected_paths)


def _workspace_role_assignments(table, field):
    """Validate the shared patterns/roles shape of `table` (named by `field`)."""
    patterns = table.get("patterns", ["thin-context"])
    if (
        not isinstance(patterns, list)
        or any(pattern != "thin-context" for pattern in patterns)
        or len(patterns) != len(set(patterns))
    ):
        raise ConfigError(f"{field}.patterns may contain thin-context once")
    overrides = table.get("roles", {})
    if not isinstance(overrides, dict) or any(
        role not in WORKSPACE_FILE_ROLES for role in overrides
    ):
        raise ConfigError(
            f"{field}.roles may assign law, map, record, memory, and boundary"
        )
    return patterns, overrides


def _describe_workspace_roles(patterns, overrides, protected_paths, roles_field="vivary.roles"):
    roles = {role: [] for role in WORKSPACE_FILE_ROLES}
    if "thin-context" in patterns:
        roles["law"] = ["AGENTS.md", ".vivary/context.md"]
        roles["map"] = [".vivary/context.md"]
        roles["boundary"] = list(dict.fromkeys([".gitignore", *protected_paths]))
    for role, values in overrides.items():
        field = f"workspace.{roles_field}.{role}"
        if not isinstance(values, list):
            raise ConfigError(f"{field} must be a list of relative paths")
        paths = [_workspace_relative_path(value, f"{roles_field}.{role}") for value in values]

